SQL:
-- FAST PATH: compare (GPT 호출 없이 고정 SQL로 조회)
-- 선수별 통산 기록
SELECT COUNT(*) AS goal_count FROM match_events WHERE player = 'Mohamed Salah' AND event_type = 'goal';
SELECT COUNT(*) AS assist_count FROM match_events WHERE assist_player = 'Mohamed Salah' AND event_type = 'goal';
SELECT m.season, COUNT(*) AS goals FROM match_events e JOIN matches m ON m.match_id = e.match_id WHERE e.player = 'Mohamed Salah' AND e.event_type = 'goal' GROUP BY m.season ORDER BY m.season;
SELECT COUNT(*) AS goal_count FROM match_events WHERE player = 'Harry Kane' AND event_type = 'goal';
SELECT COUNT(*) AS assist_count FROM match_events WHERE assist_player = 'Harry Kane' AND event_type = 'goal';
SELECT m.season, COUNT(*) AS goals FROM match_events e JOIN matches m ON m.match_id = e.match_id WHERE e.player = 'Harry Kane' AND e.event_type = 'goal' GROUP BY m.season ORDER BY m.season
